css:
@page{size:1024px 1366px;margin:0}
*{box-sizing:border-box}
html,body{margin:0;padding:0;background:transparent}
body{font-family:'Space Grotesk',sans-serif;color:#3A0A1E;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.page{width:1024px;height:1366px;position:relative;overflow:hidden;break-after:page}
.abs{position:absolute}
a{color:inherit;text-decoration:none}
.display{font-family:'Big Shoulders Display',sans-serif;font-weight:900;text-transform:uppercase;line-height:.86;letter-spacing:.005em}
.hand{font-family:'Caveat Brush',cursive}
.serif{font-family:'DM Serif Display',serif}
.label{font-weight:700;font-size:12px;letter-spacing:.16em;text-transform:uppercase}
.sheet{position:absolute;left:24px;top:24px;width:902px;height:1318px;padding:22px 30px 14px;
  display:flex;flex-direction:column}
.hdr{display:flex;align-items:center;gap:16px;flex:none;margin-bottom:12px}
.hdr .num{flex:none;width:74px;height:74px;border-radius:50%;border:3px solid #3A0A1E;box-shadow:3px 3px 0 #3A0A1E;
  display:flex;align-items:center;justify-content:center;font-family:'DM Serif Display';font-size:36px}
.hdr .t{font-size:62px}
.hdr .s{font-size:25px;margin-top:4px}
.acts{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end;max-width:58%}
.btn{display:inline-block;padding:6px 13px;border:2px solid #3A0A1E;border-radius:30px;font-weight:700;font-size:12px;
  letter-spacing:.04em;background:#fff;box-shadow:2px 2px 0 #3A0A1E;white-space:nowrap}
.body{flex:1;min-height:0;display:flex;gap:18px}
.col{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0}
.row{display:flex;gap:18px;min-width:0;min-height:0}
.g1{flex:1} .g2{flex:2} .g3{flex:3}
.bx{display:flex;flex-direction:column;min-height:0;min-width:0}
.chip{align-self:flex-start;display:inline-block;font-family:'Big Shoulders Display';font-weight:900;text-transform:uppercase;
  font-size:19px;letter-spacing:.04em;padding:3px 13px 2px;border:2.2px solid #3A0A1E;border-radius:11px;
  box-shadow:2px 2px 0 #3A0A1E;margin-bottom:6px;white-space:nowrap;line-height:1.1}
.area{flex:1;min-height:0;border:2.2px solid #3A0A1E;border-radius:16px;background:#FFFFFF;position:relative;overflow:hidden}
.fill{position:absolute;inset:0}
.tbl{flex:1;min-height:0;display:flex;flex-direction:column;border:2.2px solid #3A0A1E;border-radius:16px;overflow:hidden;background:#FFFFFF}
.tbl .th{display:flex;flex:none;height:32px;border-bottom:2.2px solid #3A0A1E}
.tbl .th div{display:flex;align-items:center;padding:0 10px;font-weight:700;font-size:11.5px;letter-spacing:.12em;text-transform:uppercase}
.tbl .tr{display:flex;flex:1;min-height:0;border-bottom:1.4px solid rgba(42,22,48,.2)}
.tbl .tr:last-child{border-bottom:0}
.tbl .tr div{border-right:1.4px solid rgba(42,22,48,.14);display:flex;align-items:center;padding:0 10px;font-size:13px}
.tbl .tr div:last-child,.tbl .th div:last-child{border-right:0}
.box{width:19px;height:19px;border:2.2px solid #3A0A1E;border-radius:6px;display:inline-block;flex:none;background:#fff}
.dot{width:22px;height:22px;border:2px solid #3A0A1E;border-radius:50%;display:inline-block;flex:none;background:#fff}
.foot{flex:none;display:flex;gap:8px;margin-top:12px;align-items:center}
.foot a{font-weight:700;font-size:11px;letter-spacing:.12em;text-transform:uppercase;padding:5px 12px;border-radius:20px;border:2px solid #3A0A1E}
.foot .pg{margin-left:auto;font-weight:700;font-size:11px;letter-spacing:.14em;opacity:.6}
.tablink{position:absolute;display:block}
/* two-pass rendering: 'st' draws what pages of one kind share, 'fg' only the per-page text (.v) and link areas */
body.st .v{visibility:hidden}
body.fg .page *{visibility:hidden}
body.fg .page .v,body.fg .page .v *{visibility:visible}
body.fg .page a:not(.v *, .v){visibility:visible;color:transparent!important;background:none!important;border-color:transparent!important;box-shadow:none!important}
.ln{border-bottom:1.6px solid rgba(42,22,48,.22)}
.field{display:flex;align-items:flex-end;gap:10px;border-bottom:1.8px solid #3A0A1E;padding-bottom:3px;min-width:0}
.field b{font-size:11.5px;letter-spacing:.14em;text-transform:uppercase;white-space:nowrap}

.hdr .t{font-family:'DM Serif Display',serif;font-weight:400;letter-spacing:.01em;white-space:nowrap;font-size:60px;color:#8E003F}
.page > .abs .display{font-family:'DM Serif Display',serif;font-weight:400}
.hdr .t{font-size:50px!important}.acts{max-width:50%}
